import { Component, input } from '@angular/core';
import { NzGridModule } from 'ng-zorro-antd/grid';

/** hrm-row — hàng grid 24 cột, bọc nz-row. Dùng với hrm-col. */
@Component({
  selector: 'hrm-row',
  imports: [NzGridModule],
  template: `<div nz-row [nzGutter]="gutter()" [nzJustify]="justify()" [nzAlign]="align()"><ng-content /></div>`,
  host: { class: 'hrm-row', style: 'display:block' },
})
export class HrmRow {
  readonly gutter = input<number | [number, number]>(16);
  readonly justify = input<'start' | 'center' | 'end' | 'space-around' | 'space-between'>('start');
  readonly align = input<'top' | 'middle' | 'bottom'>('top');
}

/** hrm-col — cột grid, bọc nz-col. span 1-24 + responsive. */
@Component({
  selector: 'hrm-col',
  imports: [NzGridModule],
  template: `
    <div nz-col [nzSpan]="span()" [nzXs]="xs()" [nzMd]="md()" [nzLg]="lg()" [nzOffset]="offset()">
      <ng-content />
    </div>
  `,
  host: { class: 'hrm-col', style: 'display:block' },
})
export class HrmCol {
  readonly span = input<number | null>(null);
  readonly xs = input<number | null>(null);
  readonly md = input<number | null>(null);
  readonly lg = input<number | null>(null);
  readonly offset = input(0);
}
